// CSD_RATIONALE_BEGIN
// Root-cause of 8.2% (attempt 62) vs 40.8% (best):
// Attempt 62 correctly used RenderedEndsWith for detection, but replaced the
// best attempt's "close at first IsCompletePrefix" with CloseSpanWithinBudget
// which seeks the LONGEST complete prefix. This caused the repetition loops:
//   n1 + n2 is complete → model keeps appending * 1 * 1 * 1... or 100//100 *
//   100//100 * 100//10 (wrong!) before CloseSpanWithinBudget finally closes.
//
// Fix: reproduce the best attempt's close-at-first-complete semantics via
// CloseSpanIfComplete (costs 0 when not yet complete, 1 when closing), while
// adopting RenderedEndsWith for robust delimiter detection.
//
// Strategy:
// 1. AppendTaskGuidance: forbid * 1 / // x * x patterns, request shortest
//    correct expression, clarify variable naming.
// 2. Unconstrained phase: UnconstrainedStep; on RenderedEndsWith(generated, "<<")
//    use EnterObservedConstrainedSpan (cost 0, no token appended).
// 3. Constrained phase: CloseSpanIfComplete first (cost 0 when open,
//    1 when closing). When not yet closed, AdaptiveConstrainedStep advances
//    one parser-valid token; AppendConstrainedToken updates state.
// 4. Emergency: with ≤ 2 steps left inside a span, CloseSpanWithinBudget
//    forces closure to prevent unclosed-span syntax failures.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span branch: insideConstrainedOut stays false until RenderedEndsWith
//   fires. EnterObservedConstrainedSpan then sets insideConstrainedOut := true
//   and currentConstrainedOut := []; parser.IsValidPrefix([]) holds by precondition.
//
//   Inside-span, CloseSpanIfComplete (closed=true): sets insideConstrainedOut
//   := false, making the implication vacuously true; currentConstrainedOut := [].
//
//   Inside-span, CloseSpanWithinBudget: its postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
//   Inside-span, AdaptiveConstrainedStep: returns EOS or a parser-valid token.
//   AppendConstrainedToken extends currentConstrainedOut by exactly that token,
//   preserving parser.IsValidPrefix because IsTokenValidNext holds for the
//   returned non-EOS token.
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Initialization: equality holds (generated = generatedPrefix, steps = 0).
//
//   Outside-span: UnconstrainedStep costs 1 step; generated grows by at most 1
//   (EOS breaks without appending). EnterObservedConstrainedSpan does not
//   change generated. steps += 1 after each token regardless, preserving the
//   bound.
//
//   Inside-span, CloseSpanIfComplete (closed=true): CloseConstrainedSpan
//   appends ">>" (1 token) and consumes 1 token-step; steps += 1 maintains
//   the bound.
//
//   Inside-span, CloseSpanWithinBudget (closeBudget = maxSteps - steps):
//   helper postcondition gives |generated_new| <= |generated_old| + closeBudget.
//   After steps := maxSteps, |generated| <= |generatedPrefix| + steps_old +
//   (maxSteps - steps_old) = |generatedPrefix| + maxSteps = |generatedPrefix| + steps.
//
//   Inside-span, AdaptiveConstrainedStep: costs 1 step; AppendConstrainedToken
//   appends exactly 1 token (EOS path breaks without appending). steps += 1
//   maintains the bound.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve this math problem step by step.\n" +
  "Wrap each intermediate symbolic result and the final answer in << >> delimiters.\n" +
  "Inside << >>, write the SHORTEST correct arithmetic expression using variable names and operators + - * / // ( ).\n" +
  "Variable names appear WITHOUT curly braces: write n1, not {n1}; write p, not {p}.\n" +
  "Do NOT append * 1, / 1, or // x * x patterns to extend an expression. Stop as soon as the expression is complete.\n" +
  "The LAST << >> span must contain the complete final answer as a single arithmetic expression.");

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      var og, oi, oc := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
    }
  } else {
    // Try to close at first complete prefix (cost 0 when not complete, 1 when closing).
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 2 {
      // Emergency close: prevent unclosed-span syntax failure.
      var closeBudget: nat := maxSteps - steps;
      var fcg, fci, fcc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := fcg;
      insideConstrainedOut := fci;
      currentConstrainedOut := fcc;
      steps := maxSteps;
    } else {
      // Generate one more parser-valid token inside the span.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

cost := steps;

